  ('if(d.aiComment){ H.push(\'<div class="sec"><h2>🤖 阪神マンからのアドバイス</h2><div style="font-size:12px;color:#475569;white-space:pre-wrap">\'+esc(d.aiComment)+\'</div></div>\'); }', 'var tsc=(d.testScores||[]); if(tsc.length){ H.push(\'<div class="sec"><h2>📝 テストの記録</h2><ul>\'); for(var ti=0;ti<tsc.length;ti++){ var tt=tsc[ti]; var tp=(tt.pct==null)?\'\':(\'（\'+tt.pct+\'%）\'); H.push(\'<li>\'+esc(tt.testDate||\'\')+\' \'+esc(tt.subject||\'\')+\' \'+esc(tt.testName||\'\')+\' … \'+(tt.score==null?\'-\':tt.score)+\'/\'+(tt.maxScore||100)+\'点\'+tp+\'</li>\'); } H.push(\'</ul></div>\'); } if(d.aiComment){ H.push(\'<div class="sec"><h2>🤖 阪神マンからのアドバイス</h2><div style="font-size:12px;color:#475569;white-space:pre-wrap">\'+esc(d.aiComment)+\'</div></div>\'); }', 'T5_karte'),
